import org.jsoup.Jsoup;
import org.jsoup.nodes.Document;
import org.jsoup.nodes.Element;
import org.jsoup.select.Elements;
import org.jsoup.select.Selector;
import org.jsoup.select.Evaluator;

public class Probe {
    static int fails = 0;
    static void check(String name, Runnable r) {
        try { r.run(); System.out.println("OK   " + name); }
        catch (Throwable t) { System.out.println("FAIL " + name + " -> " + t); fails++; }
    }
    static void expectParseEx(String name, String q) {
        try { Document d = Jsoup.parse("<div><p>x</p></div>"); d.select(q); System.out.println("FAIL " + name + " -> no exception"); fails++; }
        catch (Selector.SelectorParseException e) { System.out.println("OK   " + name + " (parse-ex)"); }
        catch (Throwable t) { System.out.println("FAIL " + name + " -> " + t); fails++; }
    }
    static void ids(String label, String html, String q, String expected) {
        Document d = Jsoup.parse(html);
        String got = d.select(q).eachAttr("id").toString();
        boolean ok = got.equals(expected);
        System.out.println((ok?"OK   ":"FAIL ") + label + " got=" + got + " want=" + expected);
        if (!ok) fails++;
    }
    public static void main(String[] a) {
        String html = "<div id=root><article id=a><h1>H1</h1><h2>H2</h2><p id=p1><b>B</b><i>I</i></p><article id=z><p>zp</p></article></article><article id=b><h1>x</h1></article></div>";

        ids("multi-branch OR", html, "article:has(> h1, + article)", "[a, b]");
        ids("one branch empty match must not kill other", html, "article:has(> nope, > h1)", "[a]");
        ids("branch no-match mix", html, "article:has(> h1, > h2)", "[a, b]");
        ids("nested has", html, "article:has(p:has(> b + i))", "[a]");
        ids("sibling tilde inside must not escape", html, "article:has(h1 ~ h2)", "[a]");
        ids("general", html, "div:has(span, p)", "[root, a, z]");

        // empty branches
        expectParseEx("empty has", "div:has()");
        expectParseEx("ws has", "div:has( )");
        expectParseEx("empty first branch", "div:has(,p)");
        expectParseEx("empty last branch", "div:has(p,)");
        expectParseEx("missing rparen", "div:has(p");
        expectParseEx("missing rhs >", "div:has(p >)");
        expectParseEx("missing rhs +", "div:has(p +)");
        expectParseEx("nested missing rparen", "div:has(p:has(span)");

        // after parse failure, doc still works
        check("doc reusable after failure", () -> {
            Document d = Jsoup.parse(html);
            try { d.select("div:has(p"); throw new AssertionError("should have thrown"); }
            catch (Selector.SelectorParseException expected) {}
            if (!d.select("article#b > h1").eachAttr("id").equals("[]")
                || d.select("h1").size() != 2) throw new AssertionError("plain select broken");
            if (!d.select("article:has(> h1)").eachAttr("id").toString().equals("[a, b]"))
                throw new AssertionError("rel select broken");
            String out = d.html();
            Document d2 = Jsoup.parse(out);
            if (!d2.select("article:has(> h1)").eachAttr("id").toString().equals("[a, b]"))
                throw new AssertionError("roundtrip broken");
        });

        // no mutation / no node creation
        check("no mutation", () -> {
            Document d = Jsoup.parse(html);
            String before = d.html();
            d.select("article:has(> h1 + h2, ~ article, p:has(i))");
            d.select("div:has(> nomatch, > p)");
            if (!before.equals(d.html())) throw new AssertionError("html changed");
        });

        // self must not count as descendant
        check("self not descendant: :has(:scope) must be empty", () -> {
            Document d = Jsoup.parse("<div id=d><p>hi</p></div>");
            // every element :has(:scope) - :scope inside :has matches only the anchor itself;
            // anchor is excluded, so no elements match
            int n = d.select(":has(:scope)").size();
            System.out.println("   :has(:scope) size=" + n);
            if (n != 0) throw new AssertionError("candidate matched itself, n=" + n);
        });

        // repeated calls, different docs, shared Evaluator
        check("shared evaluator across docs", () -> {
            Evaluator e = Selector.evaluatorOf("article:has(> h1, + article)");
            Document d1 = Jsoup.parse(html);
            Document d2 = Jsoup.parse("<article id=c><h1/></article><article id=q/>");
            String r1 = d1.select(e).eachAttr("id").toString();
            String r2 = d2.select(e).eachAttr("id").toString();
            String r1b = d1.select(e).eachAttr("id").toString();
            System.out.println("   r1=" + r1 + " r2=" + r2 + " r1b=" + r1b);
            if (!r1.equals("[a, b]") || !r2.equals("[c]") || !r1b.equals(r1))
                throw new AssertionError("state leaked between calls/docs");
        });

        // wildcard / escaped class / quoted attr / entities
        check("escapes etc", () -> {
            Document d = Jsoup.parse("<div id=x class='a.b' title='He said &quot;hi&quot; &amp; bye'><p>&nbsp;x&nbsp;</p></div>");
            if (!d.select("div:has(.a\\.b)").eachAttr("id").toString().equals("[x]")) throw new AssertionError("escaped class");
            if (!d.select("div:has([title=\"He said \\\"hi\\\" & bye\"])").eachAttr("id").toString().equals("[x]")) throw new AssertionError("quoted attr entity");
            if (!d.select("div:has(p:contains( x ))").eachAttr("id").toString().equals("[x]")) throw new AssertionError("entity text");
            if (!d.select("div:has(*)").eachAttr("id").toString().equals("[x]")) throw new AssertionError("wildcard");
        });

        // empty doc
        check("empty doc", () -> {
            Document d = Jsoup.parse("");
            if (!d.select("div:has(p)").isEmpty()) throw new AssertionError();
            if (!d.select(":has(*)").isEmpty()) throw new AssertionError();
        });

        // unclosed tags / lists / tables / nested forms
        check("tag soup", () -> {
            Document d = Jsoup.parse("<ul id=u><li>one<li id=two>two<table id=t><tr><td>x<tr id=r><td>y</table>"
                + "<form id=f1><input name=a><form id=f2><input name=b></form></form>");
            String before = d.html();
            if (!d.select("ul:has(li#two)").eachAttr("id").toString().equals("[u]")) throw new AssertionError("li");
            if (!d.select("tr:has(td)").eachAttr("id").toString().equals("[r]")) throw new AssertionError("tr ids " + d.select("tr:has(td)").eachAttr("id"));
            if (!d.select("table:has(tr#r)").eachAttr("id").toString().equals("[t]")) throw new AssertionError("table");
            if (!before.equals(d.html())) throw new AssertionError("mutated");
        });

        // parent and child both match, order stable
        check("parent-child order", () -> {
            Document d = Jsoup.parse("<section id=s1><div id=d1><p>x</p></div><div id=d2><section id=s2><p>y</p></section></div></section>");
            String ids = d.select("section:has(p), div:has(p)").eachAttr("id").toString();
            System.out.println("   order=" + ids);
            // dedupe: s1 matches via descendants p; d1, d2? d2 contains s2>p so matches; s2 matches
        });

        // multiple nested paths on same candidate
        check("multi nested paths no dup", () -> {
            Document d = Jsoup.parse("<div id=d><p id=p1><b><i>x</i></b></p><p id=p2><i>z</i></p></div>");
            Elements els = d.select("div:has(p:has(i), p b:has(i), p > b > i)");
            if (els.size() != 1 || !els.first().id().equals("d")) throw new AssertionError("got " + els.size());
        });

        System.out.println(fails == 0 ? "ALL PASS" : fails + " FAILURES");
        System.exit(fails == 0 ? 0 : 1);
    }
}
