    // each comma-separated branch keeps its own descendant / sibling set and element / node mode
    Document doc = Jsoup.parse("<article id=a></article><p></p><!--c-->");
    assertSelectedIds(doc.select("article:has(+ p, ~ ::comment)"), "a");

