        // clean adjacency: div is the immediate next node
        ids("clean +div>comment", "<div id=a></div><div><!--inside--></div>", "#a:has(+ div > ::comment)", "a");
        ids("clean +div comment", "<div id=a></div><div><span><!--inside--></span></div>", "#a:has(+ div ::comment)", "a");
        ids("clean +div span", "<div id=a></div><div><span></span></div>", "#a:has(+ div span)", "a");
        ids("clean ~div>comment", "<div id=a></div><div><!--inside--></div>", "#a:has(~ div > ::comment)", "a");
        // with intervening leaves: local rule => leading + becomes node-adjacent, blocked; check expectation
        ids("gap +div>comment", "<div id=a></div>x<div><!--inside--></div>", "#a:has(+ div > ::comment)");
        ids("gap +div comment", "<div id=a></div>x<div><span><!--inside--></span></div>", "#a:has(+ div span)");
        // internal + node steps inside sibling tree
        ids("sibtree internal+", "<div id=a></div><div><h1></h1><!--c--><b></b></div>", "#a:has(+ div h1 + ::comment + b)", "a");
        ids("sibtree internal+ block", "<div id=a></div><div><h1></h1>x<!--c--><b></b></div>", "#a:has(+ div h1 + ::comment + b)");
        // text then immediate comment semantics: local strict => blocked
        ids("text then comment +", "<div id=a></div>text<!--c-->", "#a:has(+ ::comment)");
        // element chain ignores leaves
        ids("pure elem ignores text", "<div id=a></div><b></b>x<i></i>", "#a:has(+ b + i)", "a");
        System.out.println(fails == 0 ? "ALL PASS" : fails + " FAILURES");
    }
}
