        t("not leaf, text between", "<article id=a><h1></h1>x<p class=z></p></article>", "article:has(h1 + p:not(::comment))", true);
        t("not leaf nested ~", "<article id=a><h1></h1>x<p></p><b></b></article>", "article:has(h1 ~ p:not(::text))", true);
        // :is TRANSPARENCY: leaf positively inside is is part of this chain (must keep node behavior)
        t("is(::comment) immediate", "<article id=a><h1></h1><!--c--></article>", "article:has(h1 + :is(::comment))", true);
        t("is(::comment) text blocks", "<article id=a><h1></h1>x<!--c--></article>", "article:has(h1 + :is(::comment))", false);
        t("is(::comment) leading", "<div id=a></div><!--c-->", "#a:has(+ :is(::comment))", true);
        t("is(::comment) leading text blocks", "<div id=a></div>x<!--c-->", "#a:has(+ :is(::comment))", false);
        t("is(b,comment) elem alt", "<article id=a><h1></h1><p></p></article>", "article:has(h1 + :is(::comment, p))", true);
        // :not(::text) CAN match comments (loose), should still walk nodes at anchor
        t("not(::text) matches comment", "<div id=a></div><!--c-->", "#a:has(+ :not(::text))", true);
        // positive leaf elsewhere in chain still forces all steps (documented behavior)
        t("comment+b+i blocked by text", "<article id=a></article><!--c--><b></b>x<i></i>", "article:has(+ ::comment + b + i)", false);
        t("comment+b+i clean", "<article id=a></article><!--c--><b></b><i></i>", "article:has(+ ::comment + b + i)", true);
        // not boundary at anchor: + p:not(...) anchor is element -> element walk, text ignored
        t("anchor + elem:not(node) ignores text", "<div id=a></div>x<p id=p class=z></p>", "#a:has(+ p:not(::comment))", true);
        // internal + INSIDE :is/:not still mode-handled per own contents
        t("inside is leaf step blocks", "<article id=a><div><h1></h1>x<!--c--></div></article>",
            "article:has(div:is(h1 + ::comment))", false);
        t("inside is leaf step clean", "<article id=a><div><h1></h><!--c--></div></article>",
            "article:has(div:is(h1 + ::comment))", true);
        System.out.println(fails==0?"ALL PASS":fails+" FAILURES");
        System.exit(fails==0?0:1);
    }
}
