import org.jsoup.Jsoup;
import org.jsoup.nodes.Document;
import org.jsoup.nodes.Element;
import org.jsoup.select.Elements;
import org.jsoup.select.Selector;
import java.util.*;

public class Fuzz {
    static Random rnd;
    static final String[] TAGS = {"div","p","a","b","i","span","h1","h2","section","article","ul","li","table","tr","td"};
    static String rndHtml(int depth) {
        StringBuilder sb = new StringBuilder();
        int n = 1 + rnd.nextInt(4);
        for (int i=0;i<n;i++) {
            String tag = TAGS[rnd.nextInt(TAGS.length)];
            int mode = rnd.nextInt(10);
            if (mode < 2) sb.append("<!--c").append(rnd.nextInt(3)).append("-->");
            if (mode == 2) sb.append("txt").append(rnd.nextInt(3)).append(" ");
            sb.append("<").append(tag);
            if (rnd.nextInt(3)==0) sb.append(" id=").append((char)('a'+rnd.nextInt(6))).append(rnd.nextInt(4));
            if (rnd.nextInt(4)==0) sb.append(" class=z").append(rnd.nextInt(3));
            if (rnd.nextInt(8)==0) sb.append(" title=v");
            sb.append(">");
            if (depth>0 && rnd.nextInt(2)==0) sb.append(rndHtml(depth-1));
            else if (rnd.nextInt(2)==0) sb.append("x");
            if (rnd.nextInt(12)!=0) sb.append("</").append(tag).append(">"); // sometimes unclosed
        }
        return sb.toString();
    }
    static final String[] SIMPLE = {"p","a","b","i","span","h1","h2",".z0",".z1","[title]","*","::comment","::text"};
    static final String[] COMB = {" ", " > ", " + ", " ~ "};
    static String rndBranch() {
        StringBuilder sb = new StringBuilder();
        int steps = 1 + rnd.nextInt(3);
        if (rnd.nextInt(3)==0) { // leading combinator
            sb.append(rnd.nextInt(2)==0 ? ">" : (rnd.nextInt(2)==0?"+":"~"));
        }
        for (int s=0;s<steps;s++) {
            if (s>0 || sb.length()>0) {
                String c = COMB[rnd.nextInt(COMB.length)];
                if (sb.length()==0) { if (c.trim().isEmpty()) { s--; continue; } }
                sb.append(c);
            }
            String sim = SIMPLE[rnd.nextInt(SIMPLE.length)];
            sb.append(sim);
            if (rnd.nextInt(6)==0) sb.append(":has(").append(SIMPLE[rnd.nextInt(SIMPLE.length)]).append(")");
            if (rnd.nextInt(8)==0) sb.append(":not(").append(SIMPLE[rnd.nextInt(SIMPLE.length)]).append(")");
            if (rnd.nextInt(10)==0) { sb.setLength(0); sb.append(":scope "); s=-1; }
        }
        return sb.toString().trim();
    }
    public static void main(String[] args) {
        long seed = args.length>0?Long.parseLong(args[0]):new Random().nextLong();
        rnd = new Random(seed);
        int iters = 20000;
        for (int it=0; it<iters; it++) {
            String html = rndHtml(3);
            Document d;
            try { d = Jsoup.parse(html); } catch (Throwable t) { continue; }
            String subj = TAGS[rnd.nextInt(TAGS.length)];
            String A, B;
            try { A = rndBranch(); B = rndBranch(); } catch (Throwable t) { continue; }
            String qA = subj+":has("+A+")";
            String qB = subj+":has("+B+")";
            String qAB = subj+":has("+A+", "+B+")";
            Set<String> union;
            List<String> orderA, orderB;
            try {
                orderA = d.select(qA).eachAttr("id");
            } catch (Selector.SelectorParseException e) { continue; }
            catch (Throwable t) { System.out.println("RUNTIME qA="+qA+" html="+html+" -> "+t); return; }
            try {
                orderB = d.select(qB).eachAttr("id");
            } catch (Selector.SelectorParseException e) { continue; }
            List<String> combined;
            try { combined = d.select(qAB).eachAttr("id"); }
            catch (Selector.SelectorParseException e) { System.out.println("PARSEFAIL combined="+qAB+" (A,B ok!) html="+html); return; }
            // union dedupe
            LinkedHashSet<String> u = new LinkedHashSet<>(orderA);
            u.addAll(orderB);
            if (!u.equals(new LinkedHashSet<>(combined)) || !combined.equals(new ArrayList<>(new LinkedHashSet<>(combined)))) {
                System.out.println("UNION MISMATCH seed="+seed);
                System.out.println("html="+html);
                System.out.println("A="+qA+" => "+orderA);
                System.out.println("B="+qB+" => "+orderB);
                System.out.println("AB="+qAB+" => "+combined);
                return;
            }
            // determinism + no mutation
            String h1 = d.html();
            List<String> again = d.select(qAB).eachAttr("id");
            if (!again.equals(combined) || !h1.equals(d.html())) {
                System.out.println("DETERMINISM seed="+seed+" q="+qAB); return;
            }
        }
        System.out.println("FUZZ OK seed="+seed+" iters="+iters);
    }
}
