public class Fuzz7 {
    static Random rnd;
    static final String[] TAGS = {"div","p","a","b","i","span","h1","h2","section","article","ul","li"};
    static String rndHtml(int depth) {
        StringBuilder sb = new StringBuilder();
        int n = 1 + rnd.nextInt(4);
        for (int i=0;i<n;i++) {
            String tag = TAGS[rnd.nextInt(TAGS.length)];
            int mode = rnd.nextInt(10);
