            if (mode == 2) sb.append("txt").append(rnd.nextInt(3)).append(" ");
            sb.append("<").append(tag);
            if (rnd.nextInt(4)==0) sb.append(" class=z").append(rnd.nextInt(3));
            if (rnd.nextInt(8)==0) sb.append(" title=v");
            sb.append(">");
            if (depth>0 && rnd.nextInt(2)==0) sb.append(rndHtml(depth-1));
            else if (rnd.nextInt(2)==0) sb.append("x");
            if (rnd.nextInt(12)!=0) sb.append("</").append(tag).append(">");
        }
        return sb.toString();
    }
    static final String[] SIMPLE = {"p","a","b","i","span","h1","h2",".z0",".z1","[title]","*","::comment","::text",":not(.z1)"};
    static final String[] COMB = {" ", " > ", " + ", " ~ "};
    static String rndBranch() {
        StringBuilder sb = new StringBuilder();
        int steps = 1 + rnd.nextInt(3);
        if (rnd.nextInt(3)==0) sb.append(rnd.nextInt(2)==0 ? ">" : (rnd.nextInt(2)==0?"+":"~"));
        for (int s=0;s<steps;s++) {
            if (sb.length()>0 || s>0) {
                String c = COMB[rnd.nextInt(COMB.length)];
                if (sb.length()==0 && c.trim().isEmpty()) { s--; continue; }
                sb.append(c);
            }
            sb.append(SIMPLE[rnd.nextInt(SIMPLE.length)]);
            if (rnd.nextInt(6)==0) sb.append(":has(").append(SIMPLE[rnd.nextInt(SIMPLE.length)]).append(")");
            if (rnd.nextInt(8)==0) sb.append(":not(").append(SIMPLE[rnd.nextInt(SIMPLE.length)]).append(")");
        }
        return sb.toString().trim();
    }
    static void mark(Element root, AtomicInteger id) { for (Element e : root.getAllElements()) e.attr("data-mk", String.valueOf(id.getAndIncrement())); }
    static List<String> marks(Elements es){ List<String> l=new ArrayList<>(); for(Element e:es) l.add(e.attr("data-mk")); return l; }

    public static void main(String[] args) {
        long seed = Long.parseLong(args[0]);
        rnd = new Random(seed);
        int tested=0, nonfixed=0;
        for (int it=0; it<40000; it++) {
            Document d = Jsoup.parse(rndHtml(3)); d.outputSettings().prettyPrint(false);
            mark(d, new AtomicInteger());
            String ser = d.html();
            Document dRT = Jsoup.parse(ser); dRT.outputSettings().prettyPrint(false);
            if (!ser.equals(dRT.html())) { nonfixed++; continue; } // serializer not a fixed point; skip
            String subj = TAGS[rnd.nextInt(TAGS.length)];
            String q = subj+":has("+rndBranch()+", "+rndBranch()+")";
            Evaluator ev;
            try { ev = Selector.evaluatorOf(q); } catch (Selector.SelectorParseException e) { continue; }
            tested++;
            List<String> r1, r2;
            try { r1 = marks(d.select(ev)); } catch (Throwable t) { System.out.println("RUNTIME "+t); continue; }
            try { r2 = marks(dRT.select(q)); } catch (Throwable t) { System.out.println("RT RUNTIME "+t); continue; }
            if (!r1.equals(r2)) {
                System.out.println("REAL ROUNDTRIP BUG q="+q+"\nhtml="+ser+"\n"+r1+"\n"+r2); return;
            }
