public class Malf {
    static Random rnd;
    // deliberately malformed mutations
    static String mutilate(String q) {
        int op = rnd.nextInt(7);
        switch (op) {
            case 0: { int i = q.indexOf('('); return i<0?q:q.substring(0,i+1)+q.substring(i+1); } // duplicate (
            case 1: { int i = q.lastIndexOf(')'); return i<0?q:q.substring(0,i)+q.substring(i+1); } // drop )
            case 2: return q + ")";
            case 3: { // drop char after a combinator
                for (String c : new String[]{"> ","+ ","~ "}) {
                    int i = q.indexOf(c);
                    if (i>=0) return q.substring(0,i+c.charAt(0)).trim();
                }
                return q+"(";
            }
            case 4: { int i = q.indexOf(','); return i<0?q:q.substring(0,i+1)+q.substring(i+1); } // empty after comma
            case 5: return q.replaceFirst(":", "::");
            default: return q + ",";
        }
    }
    static final String[] BASE = {
        "div:has(p)","a:has(+ div, > span)","section:has(h1 ~ h2, p > b)","x:has(p:has(a), ::comment)",
        "div:has(:scope > p)","li:has(> a[href], .z)","div:has(a, b, c)","p:has(h1 + ::comment + b)"
    };
    public static void main(String[] x) {
        rnd = new Random(Long.parseLong(x[0]));
        int bad=0;
        for (int i=0;i<50000;i++) {
            String q = mutilate(BASE[rnd.nextInt(BASE.length)]);
            Document d = Jsoup.parse("<div><p>x</p><a></a></div>");
            try { d.select(q);
                // accepted; only OK if actually still valid (some mutilations are no-ops)
                if (q.contains("(,")||q.endsWith(",")||q.endsWith(">")||q.endsWith("+")||q.endsWith("~")
                    || q.contains("()")||q.contains(":::")||q.chars().filter(c->c=='(').count()!=q.chars().filter(c->c==')').count()) {
                    System.out.println("SILENTLY ACCEPTED MALFORMED: ["+q+"]"); bad++;
                }
            } catch (Selector.SelectorParseException expected) {}
            catch (Throwable t) { System.out.println("OTHER EX for ["+q+"]: "+t); bad++; }
        }
        System.out.println(bad==0?"MALFORMED HANDLED OK seed="+x[0]:(bad+" problems"));
    }
}
