    public static void main(String[] args) {
        long seed = Long.parseLong(args[0]);
        rnd = new Random(seed);
        int tests=0;
        for (int it=0; it<40000; it++) {
            Document d = Jsoup.parse(rndHtml(3));
            String subj = TAGS[rnd.nextInt(TAGS.length)];
            String br = rndBranch();
            String q = subj+":has("+br+")";
            Evaluator ev;
            try { ev = Selector.evaluatorOf(q); } catch (Selector.SelectorParseException e) { continue; }
            // For each subject, build a doc where the subject is a LEAF (no descendants). Bare-branch :has must be false.
            // We can't strip descendants on the live doc safely; instead check the matching node is never the subject
            // by using .is() on the subject AND verifying :has(br) on a clone with children removed.
            for (Element s : d.select(subj)) {
                Element clone = s.clone();
                // remove all children nodes
                new ArrayList<>(clone.childNodes()).forEach(org.jsoup.nodes.Node::remove);
                Document ed = new Document("");
                ed.appendChild(clone);
                boolean matched = clone.is(ev);
                tests++;
                if (matched) { System.out.println("SELF MATCH q="+q+" subject="+s.tagName()+" branch="+br); return; }
            }
        }
        System.out.println("SELF OK seed="+seed+" tests="+tests);
    }
}
